// components/pages/Transactions.js - With search functionality
import React, { useState, useEffect } from 'react';
import { apiCall, escapeHtml } from '../../utils/api';

const Transactions = ({ showToast }) => {
  const [allTills, setAllTills] = useState([]);
  const [filteredTills, setFilteredTills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchType, setSearchType] = useState('all');

  const loadData = async () => {
    setLoading(true);
    const result = await apiCall('getTills');
    if (result.success) {
      setAllTills(result.tills || []);
      setFilteredTills(result.tills || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSearch = () => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) {
      setFilteredTills(allTills);
      return;
    }

    const filtered = allTills.filter(till => {
      const searchableFields = {
        name: till.name?.toLowerCase() || '',
        tillNumber: till.tillNumber?.toLowerCase() || '',
        storeNumber: till.storeNumber?.toLowerCase() || '',
        phone: till.phone || '',
        operatorId: till.operatorId?.toLowerCase() || ''
      };

      if (searchType === 'all') {
        return Object.values(searchableFields).some(field => 
          field.includes(term)
        );
      }
      return searchableFields[searchType]?.includes(term);
    });

    setFilteredTills(filtered);
    if (filtered.length === 0 && term) {
      showToast('No tills found matching your search', true);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const handleClearSearch = () => {
    setSearchTerm('');
    setFilteredTills(allTills);
  };

  const handleAddUnits = async (rowIndex, tillName) => {
    const add = prompt(`Enter number of units to ADD for ${tillName}:`);
    if (add && !isNaN(parseFloat(add)) && parseFloat(add) > 0) {
      const res = await apiCall('updateUnits', { rowIndex, addUnits: parseFloat(add) });
      if (res.success) {
        showToast(`✅ Added ${add} units successfully! New total: ${res.newUnits}`);
        loadData();
      } else {
        showToast('Failed to update units', true);
      }
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading tills...
      </div>
    );
  }

  const totalUnits = filteredTills.reduce((sum, t) => sum + (t.units || 0), 0);
  const lowUnitsCount = filteredTills.filter(t => t.units < 50 && t.status === 'active').length;

  return (
    <>
      <h3 className="section-title">
        <i className="fas fa-exchange-alt"></i> Unit Transactions
        <span className="badge-count">{filteredTills.length} tills</span>
      </h3>
      
      <div className="stats-mini-grid">
        <div className="stat-mini">
          <span className="stat-mini-label">Total Units</span>
          <span className="stat-mini-value">{totalUnits}</span>
        </div>
        <div className="stat-mini">
          <span className="stat-mini-label">Low Units (&lt; 50)</span>
          <span className="stat-mini-value" style={{ color: lowUnitsCount > 0 ? '#dc2626' : '#2b7e5a' }}>
            {lowUnitsCount}
          </span>
        </div>
      </div>

      <div className="search-bar-enhanced">
        <div className="search-input-group">
          <i className="fas fa-search search-icon"></i>
          <input 
            type="text" 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Search by name, till number, store, phone, or operator..."
            className="search-input"
          />
          {searchTerm && (
            <button className="clear-search" onClick={handleClearSearch}>
              <i className="fas fa-times"></i>
            </button>
          )}
        </div>
        <select 
          value={searchType}
          onChange={(e) => setSearchType(e.target.value)}
          className="search-select"
        >
          <option value="all">All Fields</option>
          <option value="name">Name</option>
          <option value="tillNumber">Till Number</option>
          <option value="storeNumber">Store Number</option>
          <option value="phone">Phone Number</option>
          <option value="operatorId">Operator ID</option>
        </select>
        <button className="btn-search-primary" onClick={handleSearch}>
          <i className="fas fa-search"></i> Search
        </button>
      </div>

      {filteredTills.length === 0 ? (
        <div className="empty-state">
          <i className="fas fa-inbox"></i>
          <br />No tills found matching your search
        </div>
      ) : (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Phone</th>
                <th>Till Number</th>
                <th>Store</th>
                <th>Operator</th>
                <th>Units</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredTills.map((till, index) => {
                const isLowUnits = till.units < 50 && till.status === 'active';
                return (
                  <tr key={index} className={isLowUnits ? 'low-units-row' : ''}>
                    <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                    <td><i className="fas fa-phone"></i> {escapeHtml(till.phone || '-')}</td>
                    <td><span className="till-badge">{escapeHtml(till.tillNumber || '-')}</span></td>
                    <td>{escapeHtml(till.storeNumber || '-')}</td>
                    <td><span className="operator-badge">{escapeHtml(till.operatorId || '-')}</span></td>
                    <td>
                      <span className={`units-display ${isLowUnits ? 'low-units' : ''}`}>
                        {till.units || 0} units
                        {isLowUnits && <i className="fas fa-exclamation-triangle low-units-icon"></i>}
                      </span>
                    </td>
                    <td>
                      {till.status === 'active' ? 
                        <span className="badge badge-success"><i className="fas fa-check-circle"></i> Active</span> : 
                        <span className="badge badge-danger"><i className="fas fa-times-circle"></i> Inactive</span>
                      }
                    </td>
                    <td>
                      <button 
                        className="btn-add-units" 
                        onClick={() => handleAddUnits(till.rowIndex, till.name)}
                        disabled={till.status !== 'active'}
                      >
                        <i className="fas fa-plus-circle"></i> Add Units
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
};

export default Transactions;
